// Add to log + prepare reply text
// Matches src/careerlog/api.py exactly

const config = $('Config').first().json;
const expectedChatId = String(config.chatId);
const checkinToken = config.checkinToken;
const checkinUrl = 'http://127.0.0.1:8765/entries';

const updates = $input.first().json.result || [];
const staticData = $getWorkflowStaticData('global');
let maxUpdateId = staticData.lastUpdateId || 0;

const replies = [];

for (const update of updates) {
  if (update.update_id > maxUpdateId) {
    maxUpdateId = update.update_id;
  }

  const message = update.message;
  if (!message || !message.text) continue;

  const chatId = String(message.chat?.id);
  if (chatId !== expectedChatId) continue;

  const text = message.text.trim();
  if (!text) continue;

  let replyText = 'Not added: the check-in service did not answer';
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: checkinUrl,
      headers: {
        'X-Token': checkinToken,
        'Content-Type': 'application/json'
      },
      body: { message: text },
      json: true,
      timeout: 10000
    });

    if (response && response.id) {
      replyText = 'Added to career-log.';
    } else if (response && response.duplicate) {
      replyText = 'Already in your log.';
    } else if (response && response.error) {
      replyText = `Not added: ${response.error}`;
    } else {
      replyText = 'Not added: unexpected response from check-in service';
    }
  } catch (error) {
    const msg = error.message || '';
    if (msg.includes('token') || msg.includes('401')) {
      replyText = 'Not added: bad or missing token';
    } else {
      replyText = `Not added: ${msg || 'service error'}`;
    }
  }

  replies.push({
    json: {
      chatId,
      text: replyText,
      originalText: text
    }
  });
}

if (maxUpdateId > (staticData.lastUpdateId || 0)) {
  staticData.lastUpdateId = maxUpdateId;
}

return replies.length
  ? replies
  : [{ json: { chatId: expectedChatId, text: null, skip: true } }];

// Make reply – just pass through the prepared reply (filter out skips)
const items = $input.all();
return items.filter(item => !item.json.skip && item.json.text);
